import {layouts} from './layouts.js';
import {createProject,validateProject,newEntry,uid,clone,History,safeUrl} from './project.js';
import {escapeHtml as esc} from './engine.js';
const dict={pl:{appearance:'Wygląd',home:'Strona główna',content:'Treści',menu:'Menu',project:'Projekt',brand:'Nazwa marki',email:'E-mail kontaktowy',accent:'Akcent',background:'Tło',ink:'Tekst',font:'Krój nagłówków',serif:'Szeryfowy',sans:'Bezszeryfowy',radius:'Zaokrąglenia',width:'Szerokość serwisu',fontSize:'Rozmiar tekstu',heroTitle:'Nagłówek główny',heroText:'Opis pod nagłówkiem',heroImage:'Adres zdjęcia głównego',heroAlt:'Opis zdjęcia (alt)',heroLabel:'Etykieta nad nagłówkiem',heroButton:'Tekst przycisku',heroTarget:'Cel przycisku',showHero:'Pokaż sekcję główną',showPosts:'Pokaż artykuły i oferty',postsTitle:'Nagłówek listy treści',footer:'Tekst w stopce',errorTitle:'Nagłówek strony 404',errorText:'Opis strony 404',sections:'Dodatkowe sekcje',addText:'+ Tekst',addImage:'+ Zdjęcie',addCta:'+ Przycisk',text:'Tekst',image:'Zdjęcie',cta:'Wezwanie do działania',title:'Tytuł',body:'Treść',alt:'Opis zdjęcia (alt)',url:'Docelowy adres URL',button:'Tekst przycisku',remove:'Usuń',up:'W górę',down:'W dół',duplicate:'Duplikuj',article:'Artykuł',product:'Oferta',page:'Podstrona',addArticle:'+ Artykuł',addProduct:'+ Oferta',addPage:'+ Strona',excerpt:'Krótki opis',category:'Kategoria',author:'Autor',price:'Cena / warunki',imageUrl:'Adres zdjęcia',slug:'Slug podstrony',entryUrl:'Adres w Bloggerze (po publikacji)',published:'Gotowe do publikacji',draft:'Szkic',ready:'Gotowe',empty:'Brak treści. Dodaj pierwszy element.',preview:'Pokaż w podglądzie',copy:'Kopiuj HTML tej treści',formatHint:'Formatowanie: **pogrubienie**, *kursywa*, ## nagłówek, - lista, > cytat. Każdy nowy wiersz to akapit.',bold:'Pogrubienie',italic:'Kursywa',heading:'Nagłówek',list:'Lista',quote:'Cytat',addMenu:'+ Pozycja menu',label:'Nazwa pozycji',target:'Link prowadzi do',external:'Adres zewnętrzny',save:'Zapisz projekt',saved:'Zapisano na tym urządzeniu',failed:'Nie udało się zapisać. Pobierz kopię projektu.',download:'Pobierz projekt JSON',import:'Wczytaj projekt JSON',reset:'Przywróć motyw startowy',projectHelp:'Projekt zapisuje się automatycznie w tej przeglądarce. Plik JSON pozwala przenieść go na inne urządzenie. Każdy motyw ma własny projekt.',bloggerHelp:'Pakiet zawiera XML wyglądu i osobne pliki HTML Twoich treści. Artykuły oraz strony dodajesz do Bloggera zgodnie z instrukcją w paczce.',undo:'Cofnij',redo:'Ponów',language:'Język treści',imported:'Projekt wczytany',invalid:'Nieprawidłowy plik lub projekt innego motywu.',limit:'Osiągnięto limit elementów.',urlError:'Podaj pełny adres http:// lub https://.',copied:'HTML treści skopiowany',copyError:'Nie udało się skopiować. Pobierz pakiet.',unsaved:'Zmiany w pamięci',restoreInfo:'Możesz cofnąć usunięcie lub przywrócenie motywu przyciskiem Cofnij.',contentInfo:'Gotowe treści pojawiają się na stronie głównej podglądu. Szkice pozostają w projekcie i pakiecie, bez kart na stronie głównej.'},en:{appearance:'Design',home:'Homepage',content:'Content',menu:'Menu',project:'Project',brand:'Brand name',email:'Contact email',accent:'Accent',background:'Background',ink:'Text',font:'Heading font',serif:'Serif',sans:'Sans serif',radius:'Corner radius',width:'Site width',fontSize:'Text size',heroTitle:'Main heading',heroText:'Introduction',heroImage:'Hero image URL',heroAlt:'Image description (alt)',heroLabel:'Eyebrow label',heroButton:'Button text',heroTarget:'Button destination',showHero:'Show hero section',showPosts:'Show posts and offers',postsTitle:'Content list heading',footer:'Footer text',errorTitle:'404 heading',errorText:'404 description',sections:'Additional sections',addText:'+ Text',addImage:'+ Image',addCta:'+ Button',text:'Text',image:'Image',cta:'Call to action',title:'Title',body:'Body',alt:'Image description (alt)',url:'Destination URL',button:'Button text',remove:'Delete',up:'Move up',down:'Move down',duplicate:'Duplicate',article:'Article',product:'Offer',page:'Page',addArticle:'+ Article',addProduct:'+ Offer',addPage:'+ Page',excerpt:'Excerpt',category:'Category',author:'Author',price:'Price / terms',imageUrl:'Image URL',slug:'Page slug',entryUrl:'Blogger URL (after publishing)',published:'Ready to publish',draft:'Draft',ready:'Ready',empty:'No content yet. Add the first item.',preview:'Show in preview',copy:'Copy this content as HTML',formatHint:'Formatting: **bold**, *italic*, ## heading, - list, > quote. Each new line is a paragraph.',bold:'Bold',italic:'Italic',heading:'Heading',list:'List',quote:'Quote',addMenu:'+ Menu item',label:'Label',target:'Destination',external:'External URL',save:'Save project',saved:'Saved on this device',failed:'Could not save. Download a project backup.',download:'Download project JSON',import:'Import project JSON',reset:'Restore starter theme',projectHelp:'Changes save automatically in this browser. Download JSON to move the project to another device. Each theme has its own project.',bloggerHelp:'The package includes theme XML and separate HTML files for your content. Add posts and pages to Blogger following the package instructions.',undo:'Undo',redo:'Redo',language:'Content language',imported:'Project imported',invalid:'Invalid file or a project for another theme.',limit:'Item limit reached.',urlError:'Enter a full http:// or https:// URL.',copied:'Content HTML copied',copyError:'Could not copy. Download the package.',unsaved:'Changes in memory',restoreInfo:'Use Undo to restore deleted items or undo a theme reset.',contentInfo:'Ready content appears on the preview homepage. Drafts stay in the project and package without homepage cards.'}};
export function createEditor({state,refresh,preview,notify,download,entryContent}){
let tab='appearance',activeId='article',saveFailed=false,trackedInput=null;const histories=new Map();
const tr=()=>dict[state.lang],current=()=>state.options[state.selected.id].project;
const history=()=>{if(!histories.has(state.selected.id))histories.set(state.selected.id,new History());return histories.get(state.selected.id);};
function ensure(theme){let project=state.options[theme.id]?.project;try{if(project)project=validateProject(project,theme.id);}catch{project=null;}if(!project){try{const raw=localStorage.getItem('forma.project.'+theme.id);if(raw)project=validateProject(JSON.parse(raw),theme.id);}catch{}}state.options[theme.id]={project:project||createProject(theme,state.lang,state.options[theme.id])};}
function save(){try{localStorage.setItem('forma.project.'+state.selected.id,JSON.stringify(current()));saveFailed=false;}catch{saveFailed=true;}const el=document.querySelector('#save-status');if(el){el.textContent=saveFailed?tr().failed:tr().saved;el.classList.toggle('save-failed',saveFailed);}updateHistory();}
function updateHistory(){const h=history();for(const [action,disabled] of [['undo',!h.past.length],['redo',!h.future.length]]){const b=document.querySelector(`[data-editor="${action}"]`);if(b)b.disabled=disabled;}}
function act(fn){history().remember(current());fn(current());save();refresh();}
function setProject(p){state.options[state.selected.id]={project:p};}
function field(label,key,value,type='text',scope='project',index=''){const attrs=`data-edit="${key}" data-scope="${scope}" data-index="${index}"`;return `<label class="edit-field"><span>${esc(label)}</span>${type==='textarea'?`<textarea ${attrs} rows="${key==='body'?10:3}" maxlength="${key==='body'?100000:30000}">${esc(value)}</textarea>`:type==='checkbox'?`<input ${attrs} type="checkbox" ${value?'checked':''}/>`:`<input ${attrs} type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="1000"':''}/>`}</label>`;}
function select(label,key,value,choices,scope='project',index=''){return `<label class="edit-field"><span>${esc(label)}</span><select data-edit="${key}" data-scope="${scope}" data-index="${index}">${choices.map(([id,title])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;}
const b=(action,label,extra='',cls='secondary')=>`<button class="${cls}" data-editor="${action}" ${extra}>${label}</button>`;
function targets(p){return [['home',tr().home],...p.entries.map(e=>[e.id,e.title||tr()[e.kind]]),['404','404']];}
function rowActions(scope,index){const t=tr(),count=current()[scope].length;return `<div class="row-actions">${b('up','↑',`data-scope="${scope}" data-index="${index}" aria-label="${t.up}" ${index===0?'disabled':''}`)}${b('down','↓',`data-scope="${scope}" data-index="${index}" aria-label="${t.down}" ${index===count-1?'disabled':''}`)}${b('duplicate',t.duplicate,`data-scope="${scope}" data-index="${index}"`)}${b('remove',t.remove,`data-scope="${scope}" data-index="${index}"`,'danger-button')}</div>`;}
function bodyField(row,scope,index){const t=tr();return `<div class="format-toolbar">${[['bold','B'],['italic','I'],['heading','H2'],['list','•'],['quote','❞']].map(([action,label])=>b('format',label,`data-format="${action}" data-scope="${scope}" data-index="${index}" aria-label="${t[action]}"`)).join('')}</div>${field(t.body,'body',row.body,'textarea',scope,index)}<p class="editor-hint">${t.formatHint}</p>`;}
function panel(){const t=tr(),p=current();if(tab==='appearance')return `${select(state.lang==='pl'?'Układ całego serwisu':'Website layout','siteLayout',p.siteLayout,Object.entries(layouts).map(([id,label])=>[id,label[state.lang]]))}<p class="editor-hint">${state.lang==='pl'?'Zmienia kompozycję nagłówka, strony głównej, listy treści i podstron. Twoje teksty pozostają bez zmian.':'Changes the header, homepage, content list and detail layouts. Your content is preserved.'}</p>${field(t.brand,'brand',p.brand)}${field(t.email,'email',p.email,'email')}<div class="color-fields">${['accent','background','ink'].map(k=>field(t[k],k,p[k],'color')).join('')}</div>${select(t.font,'font',p.font,[['serif',t.serif],['sans',t.sans]])}${[['radius',0,40,1,'px'],['width',900,1500,20,'px'],['fontSize',14,24,1,'px']].map(([key,min,max,step,unit])=>`<label class="edit-field"><span>${t[key]} <output id="out-${key}">${p[key]}${unit}</output></span><input data-edit="${key}" data-scope="project" type="range" min="${min}" max="${max}" step="${step}" value="${p[key]}"/></label>`).join('')}${field(t.footer,'footer',p.footer,'textarea')}`;
if(tab==='home')return `${field(t.showHero,'showHero',p.showHero,'checkbox')}${field(t.heroLabel,'heroLabel',p.heroLabel)}${field(t.heroTitle,'heroTitle',p.heroTitle,'textarea')}${field(t.heroText,'heroText',p.heroText,'textarea')}${field(t.heroImage,'heroImage',p.heroImage,'url')}${field(t.heroAlt,'heroAlt',p.heroAlt)}${field(t.heroButton,'heroButton',p.heroButton)}${select(t.heroTarget,'heroTarget',p.heroTarget,targets(p))}${field(t.showPosts,'showPosts',p.showPosts,'checkbox')}${field(t.postsTitle,'postsTitle',p.postsTitle)}<h3>${t.sections}</h3>${p.sections.map((s,i)=>`<details class="editor-card" open><summary>${t[s.type]} ${i+1}</summary>${field(t.title,'title',s.title,'text','sections',i)}${s.type==='image'?field(t.imageUrl,'image',s.image,'url','sections',i)+field(t.alt,'alt',s.alt,'text','sections',i):''}${bodyField(s,'sections',i)}${s.type==='cta'?field(t.button,'button',s.button,'text','sections',i)+field(t.url,'url',s.url,'text','sections',i):''}${rowActions('sections',i)}</details>`).join('')}<div class="add-actions">${b('add-section',t.addText,'data-type="text"')}${b('add-section',t.addImage,'data-type="image"')}${b('add-section',t.addCta,'data-type="cta"')}</div>`;
if(tab==='content'){const entry=p.entries.find(e=>e.id===activeId)||p.entries[0];if(entry)activeId=entry.id;const index=p.entries.indexOf(entry);return `<div class="add-actions">${['article','product','page'].map(kind=>b('add-entry',t['add'+kind[0].toUpperCase()+kind.slice(1)],`data-kind="${kind}"`)).join('')}</div><p class="editor-hint">${t.contentInfo}</p><div class="entry-list">${p.entries.map(e=>`<button class="entry-button ${e.id===activeId?'active':''}" data-editor="select-entry" data-id="${e.id}"><span>${esc(e.title||t[e.kind])}</span><small>${t[e.kind]} · ${e.published?t.ready:t.draft}</small></button>`).join('')}</div>${entry?`<div class="entry-edit">${field(t.title,'title',entry.title,'text','entries',index)}${field(t.published,'published',entry.published,'checkbox','entries',index)}${field(t.excerpt,'excerpt',entry.excerpt,'textarea','entries',index)}${field(t.imageUrl,'image',entry.image,'url','entries',index)}${field(t.alt,'alt',entry.alt,'text','entries',index)}${entry.kind!=='page'?field(t.category,'category',entry.category,'text','entries',index)+field(t.author,'author',entry.author,'text','entries',index):field(t.slug,'slug',entry.slug,'text','entries',index)}${entry.kind==='product'?field(t.price,'price',entry.price,'text','entries',index):''}${bodyField(entry,'entries',index)}${field(t.entryUrl,'url',entry.url,'text','entries',index)}${b('preview-entry',t.preview,`data-id="${entry.id}"`,'primary')}${b('copy-entry',t.copy,`data-id="${entry.id}"`)}${rowActions('entries',index)}</div>`:`<p>${t.empty}</p>`}`;}
if(tab==='menu')return `${p.menu.map((item,i)=>`<div class="editor-card">${field(t.label,'label',item.label,'text','menu',i)}${select(t.target,'target',item.target,[...targets(p),['external',t.external]],'menu',i)}${item.target==='external'?field(t.url,'url',item.url,'text','menu',i):''}${rowActions('menu',i)}</div>`).join('')}${b('add-menu',t.addMenu)}<h3>404</h3>${field(t.errorTitle,'errorTitle',p.errorTitle)}${field(t.errorText,'errorText',p.errorText,'textarea')}`;
return `<p class="editor-note">${t.projectHelp}</p>${select(t.language,'language',p.language,[['pl','Polski'],['en','English']])}<div class="project-actions">${b('save',t.save,'','primary')}${b('download',t.download)}<label class="secondary import-label">${t.import}<input id="project-import" type="file" accept=".json,application/json"/></label>${b('reset',t.reset,'','danger-button')}</div><p class="editor-hint">${t.restoreInfo}</p><div class="editor-note">${t.bloggerHelp}</div>`;}
function mount(){const el=document.querySelector('#studio-controls');if(!el)return;const t=tr();el.innerHTML=`<div class="editor-top"><strong>Forma Studio</strong><div>${b('undo','↶',`aria-label="${t.undo}" title="${t.undo}"`)}${b('redo','↷',`aria-label="${t.redo}" title="${t.redo}"`)}</div></div><div id="save-status" class="save-status" role="status">${saveFailed?t.failed:t.saved}</div><nav class="editor-tabs" aria-label="Forma Studio">${['appearance','home','content','menu','project'].map(key=>`<button data-editor="tab" data-tab="${key}" class="${key===tab?'active':''}" aria-pressed="${key===tab}">${t[key]}</button>`).join('')}</nav><div class="editor-panel">${panel()}</div>`;updateHistory();}
document.addEventListener('focusin',e=>{if(e.target.matches('#studio-controls [data-edit]')){history().remember(current());trackedInput=e.target;}});
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('#studio-controls [data-edit]'))return;if(trackedInput!==el||el.tagName==='SELECT'||el.type==='checkbox'){history().remember(current());trackedInput=el;}const p=current(),row=el.dataset.scope==='project'?p:p[el.dataset.scope][Number(el.dataset.index)];if(!row)return;row[el.dataset.edit]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;const output=document.querySelector('#out-'+el.dataset.edit);if(output)output.textContent=el.value+'px';if(el.type==='url'){el.setCustomValidity(el.value&&!safeUrl(el.value,true)?tr().urlError:'');}save();preview();if(el.tagName==='SELECT'&&el.dataset.scope==='menu')mount();});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-editor]');if(!el||!state.selected)return;const a=el.dataset.editor,p=current(),t=tr(),index=Number(el.dataset.index),scope=el.dataset.scope;
if(a==='tab'){tab=el.dataset.tab;if(tab==='home')state.page='home';mount();preview();return;}
if(a==='select-entry'||a==='preview-entry'){activeId=el.dataset.id;state.page=activeId;mount();preview();return;}
if(a==='undo'||a==='redo'){const value=history()[a](p);if(value){setProject(value);if(!['home','404',...value.entries.map(e=>e.id)].includes(state.page))state.page='home';save();refresh();}return;}
if(a==='save'){save();notify(saveFailed?t.failed:t.saved);return;}
if(a==='download'){download(`forma-${state.selected.id}.json`,JSON.stringify(p,null,2),'application/json');return;}
if(a==='reset'){act(()=>{setProject(createProject(state.selected,p.language));state.page='home';activeId='article';});return;}
if(a==='copy-entry'){const entry=p.entries.find(x=>x.id===el.dataset.id);try{await navigator.clipboard.writeText(entryContent(entry,p,entry.kind==='page'));notify(t.copied);}catch{notify(t.copyError);}return;}
if(a==='add-entry'){if(p.entries.length>=100)return notify(t.limit);act(p=>{const item=newEntry(el.dataset.kind,p.language);item.slug=item.id;p.entries.push(item);activeId=item.id;state.page=item.id;});return;}
if(a==='add-section'){if(p.sections.length>=30)return notify(t.limit);act(p=>p.sections.push({id:uid(),type:el.dataset.type,title:t[el.dataset.type],body:'',image:'',alt:'',button:p.language==='pl'?'Zobacz więcej':'Learn more',url:''}));return;}
if(a==='add-menu'){if(p.menu.length>=20)return notify(t.limit);act(p=>p.menu.push({id:uid(),label:t.label,target:'home',url:''}));return;}
if(a==='format'){const textarea=document.querySelector(`textarea[data-scope="${scope}"][data-index="${index}"][data-edit="body"]`);if(!textarea)return;history().remember(p);const start=textarea.selectionStart,end=textarea.selectionEnd,selected=textarea.value.slice(start,end)||t.text;const marker={bold:'**',italic:'*',heading:'## ',list:'- ',quote:'> '}[el.dataset.format];const inline=['bold','italic'].includes(el.dataset.format);const value=(inline?'':start&&textarea.value[start-1]!=='\n'?'\n':'')+marker+selected+(inline?marker:'');textarea.setRangeText(value,start,end,'select');p[scope][index].body=textarea.value;save();preview();textarea.focus();return;}
if(['up','down','duplicate','remove'].includes(a)&&['entries','sections','menu'].includes(scope)){const list=p[scope];if(!list[index])return;if(a==='duplicate'&&list.length>=({entries:100,sections:30,menu:20}[scope]))return notify(t.limit);act(p=>{const items=p[scope];if(a==='remove'){const [removed]=items.splice(index,1);if(scope==='entries'){p.menu=p.menu.filter(n=>n.target!==removed.id);if(p.heroTarget===removed.id)p.heroTarget='home';if(state.page===removed.id)state.page='home';}}else if(a==='duplicate'){const item=clone(items[index]);item.id=uid();if(scope==='entries'){item.title+=' (copy)';item.slug=item.id;item.url='';activeId=item.id;state.page=item.id;}items.splice(index+1,0,item);}else{const next=index+(a==='up'?-1:1);if(next>=0&&next<items.length)[items[index],items[next]]=[items[next],items[index]];}});}
});
document.addEventListener('change',async e=>{if(e.target.id!=='project-import')return;const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error();const p=validateProject(JSON.parse(await file.text()),state.selected.id);act(()=>{setProject(p);state.page='home';activeId=p.entries[0]?.id||'';});notify(tr().imported);}catch{notify(tr().invalid);}});
return {ensure,mount,save};
}
